[data-workspace-area="conversation"] .messages-timeline-scroll,[data-chat-header]{background:transparent!important}
[data-chat-header]{backdrop-filter:blur(6px)}
[data-user-message-bubble]{background:rgba(15,26,54,.8)!important;border:1px solid rgba(244,96,106,.35)!important;backdrop-filter:blur(4px)}
.chat-markdown{text-shadow:0 1px 2px rgba(0,0,0,.95),0 0 6px rgba(0,0,0,.6)}
.chat-markdown-codeblock{background:rgba(15,26,54,.88)!important}
[data-slot="composer-host"]{background:rgba(15,26,54,.82)!important;backdrop-filter:blur(8px);border-color:rgba(244,96,106,.4)!important}
